 'vag':'https://www.cancer.org/cancer/types/vaginal-cancer/about/key-statistics.html',
}
for k,u in urls.items():
    try:
        html = requests.get(u, timeout=20, headers={'User-Agent':'Mozilla/5.0'}).text
        print('\nURL',k,u,'status ok len',len(html))
        for pat in [r'5-year relative survival[^<]{0,120}', r'About [0-9,]+ new cases', r'about [0-9,]+ cases per year', r'about [0-9,]+ new cancers', r'vaginal cancer[^<]{0,200}']:
            m = re.search(pat, html, re.I)
            if m:
                print('MATCH:', m.group(0)[:300])
    except Exception as e:
        print('ERR',k,e)
