import requests, re
urls = {
 'common':'https://seer.cancer.gov/statfacts/html/common.html',
 'meso':'https://www.cancer.org/cancer/types/malignant-mesothelioma/detection-diagnosis-staging/survival-statistics.html',
 'vag':'https://www.cancer.org/cancer/types/vaginal-cancer/about/key-statistics.html',
}
for k,u in urls.items():
    try:
        html = requests.get(u, timeout=20, headers={'User-Agent':'Mozilla/5.0'}).text
        print('\nURL',k,u,'len',len(html))
        snippets=[]
        for pat in [r'.{0,80}5-year relative survival.{0,180}', r'.{0,80}About [0-9,]+ new cases.{0,120}', r'.{0,80}about [0-9,]+ cases per year.{0,120}', r'.{0,80}about [0-9,]+ new cancers.{0,120}', r'.{0,80}vaginal cancer.{0,200}']:
            for m in re.finditer(pat, html, re.I|re.S):
                snippets.append(re.sub(r'\s+',' ',m.group(0)))
        for s in snippets[:5]:
            print('MATCH:', s[:500])
    except Exception as e:
        print('ERR',k,e)
